class LegacyWidget { // C++98-style, no move ops
public:
    LegacyWidget& operator=(const LegacyWidget&) { /* deep copy logic */ return *this; }
    LegacyWidget(const LegacyWidget&) { /* deep copy logic */ }
    LegacyWidget() = default;
};

class ModernWidget {
private:
    std::string s;       // Has move operations
    LegacyWidget lw;     // Only has copy operations
public:
    // Compiler will generate move ops for ModernWidget
};

ModernWidget mw1;
// In the generated move constructor for ModernWidget:
// - mw2.s is move-constructed from mw1.s
// - mw2.lw is copy-constructed from mw1.lw (fallback)
ModernWidget mw2 = std::move(mw1);
